hubSubjects.python={name:'Python 课堂',mark:'Py',tag:'从第一行到巡检摘要',description:'输出、变量、判断、循环、函数、JSON 与文件；在网页运行代码，按步骤验证。',tone:'blue'};
let pythonIndex=0,pythonState={},pythonWorker=null,pythonRuntime='idle',pythonBusy=false,pythonTimer=null,pythonRunId=0,pythonRuntimeNote='';
try{const data=JSON.parse(localStorage.getItem('learning-python-v1'));if(data&&typeof data==='object'&&!Array.isArray(data))pythonState=data;}catch(e){}
function pythonCurrent(){return pythonLessons[pythonIndex];}
function pythonAttempt(){const c=pythonCurrent();let a=pythonState[c.id];if(!a||a.version!==1||typeof a.code!=='string')a=pythonState[c.id]={version:1,read:false,phase:'learn',code:c.starter,verifiedCode:null,confirmed:false,answer:null,checked:false,result:null};return a;}
function pythonPassed(i){const c=pythonLessons[i],a=pythonState[c.id];return !!a&&a.version===1&&a.read===true&&a.confirmed===true&&a.verifiedCode===a.code&&a.result?.passed===true&&a.answer===c.quiz.answer&&a.checked===true;}
function pythonUnlocked(i){return Number.isInteger(i)&&i>=0&&i<pythonLessons.length&&pythonLessons.slice(0,i).every((_,j)=>pythonPassed(j));}
function pythonNext(){const i=pythonLessons.findIndex((_,i)=>!pythonPassed(i));return i<0?pythonLessons.length-1:i;}
function pythonSave(){try{localStorage.setItem('learning-python-v1',JSON.stringify(pythonState));}catch(e){toast('无法保存 Python 进度，请先复制代码草稿。');}}
function pythonInvalidate(a){a.verifiedCode=null;a.confirmed=false;a.checked=false;}
function pythonStop(message='已停止。代码与进度保留，可以重新准备运行环境。'){
 if(pythonTimer)clearTimeout(pythonTimer);pythonTimer=null;pythonWorker?.terminate();pythonWorker=null;pythonBusy=false;pythonRuntime='idle';pythonRunId++;pythonRuntimeNote=message;
}
function pythonOpen(i){if(!pythonUnlocked(i))return toast('先通过上一课的代码练习与小测。');if(pythonBusy)pythonStop();pythonIndex=i;const a=pythonAttempt();if(!a.read)a.phase='learn';if(a.phase==='quiz'&&!a.confirmed)a.phase='practice';view='python-course';hubSubject='python';render();window.scrollTo({top:0,behavior:'instant'});}
function pythonPrepare(){if(pythonRuntime==='loading'||pythonRuntime==='ready')return;pythonRuntime='loading';pythonRuntimeNote='正在准备 Python 环境；首次加载可能需要稍等。';
 try{const worker=pythonWorker=new Worker('python-worker.js?v=20261009-7',{type:'module'});pythonTimer=setTimeout(()=>{if(pythonWorker===worker){pythonStop('环境准备超时。请检查网络后点击“准备 Python 环境”重试。');if(view==='python-course')render();}},60000);
 worker.onmessage=({data})=>{if(pythonWorker!==worker)return;if(data.type==='ready'){clearTimeout(pythonTimer);pythonTimer=null;pythonRuntime='ready';pythonRuntimeNote='环境已就绪，输入代码后点击“运行代码并验证”。';}
 else if(data.type==='init-error'){pythonStop('环境未能准备完成，请稍后重试。');}
 else if(data.type==='result'&&data.id===pythonRunId){clearTimeout(pythonTimer);pythonTimer=null;pythonBusy=false;const a=pythonAttempt();a.result=data;a.verifiedCode=data.passed?a.code:null;a.confirmed=false;a.checked=false;pythonSave();}
 if(view==='python-course')render();};worker.onerror=()=>{if(pythonWorker!==worker)return;pythonStop('运行环境遇到错误，请重新准备；代码草稿仍保留。');if(view==='python-course')render();};worker.postMessage({type:'init'});
 }catch(e){pythonStop('浏览器未能启动运行环境，请尝试更新浏览器后重试。');}render();}
function pythonRun(){const a=pythonAttempt(),c=pythonCurrent();if(!a.read||a.phase!=='practice'||pythonBusy)return;if(pythonRuntime!=='ready')return toast('先准备 Python 环境，准备完成后再运行。');if(!a.code.trim())return toast('先输入本课代码。');if(a.code.length>12000)return toast('课堂代码请控制在 12000 字以内。');pythonInvalidate(a);a.result=null;pythonBusy=true;const id=++pythonRunId;pythonTimer=setTimeout(()=>{pythonStop('本次运行超过 8 秒，已停止。检查循环能否结束，再准备环境重试。');if(view==='python-course')render();},8000);pythonWorker.postMessage({type:'run',id,code:a.code,checks:c.checks,syntax:c.syntax,expected:c.output});pythonSave();render();}
function pythonRoadmapHTML(){const next=pythonNext(),done=pythonLessons.filter((_,i)=>pythonPassed(i)).length;return `<main class="hub-main"><div class="page-head"><div><div class="eyebrow">Python / 零基础课堂</div><h1>从一句输出，到一份巡检摘要。</h1><p>16 课分四个阶段。先读解释，再运行代码、确认结果，最后通过小测。无需本地安装 Python。</p></div><button class="primary" data-python="lesson" data-index="${next}">${done?'继续第 '+(next+1)+' 课':'从第 1 课开始'}</button></div><section class="section"><h2>你会学到什么？</h2><p>从变量、条件与循环起步，逐渐学会解析 JSON、读教学日志、处理坏数据和生成报告。课堂使用真实 Python；日志与接口数据是固定的教学样本，不连接工作服务器。</p><p>${done}/${pythonLessons.length} 课已通过 · 代码草稿与进度保存在本设备；运行文件每次重置。</p><a href="https://docs.python.org/zh-cn/3/tutorial/index.html" target="_blank" rel="noopener noreferrer">Python 官方中文教程（补充参考）</a></section>${pythonStages.map((s,n)=>`<section class="section"><h2>阶段 ${n+1} · ${esc(s)}</h2><div class="path-list">${pythonLessons.map((c,i)=>c.stage===n?`<article class="path-card ${pythonUnlocked(i)?'':'locked'}"><span class="path-number">${i+1}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.goal)}</p><details><summary>预览本课讲解</summary><p>${esc(c.why)}</p><p>${esc(c.explain)}</p><pre>${esc(c.example)}</pre></details></div><button class="${pythonUnlocked(i)?'primary':'secondary'}" data-python="lesson" data-index="${i}" ${pythonUnlocked(i)?'':'disabled'}>${pythonPassed(i)?'复习':pythonUnlocked(i)?'开始学习':'先通过上一课'}</button></article>`:'').join('')}</div></section>`).join('')}</main>`;}
function pythonFlowCue(phase,goal){const cues={learn:['现在：读懂本课代码','下一步：读完逐行示例，点击“我读懂了，开始写代码”。'],practice:['现在：写代码并验证','下一步：准备 Python 环境，运行代码；通过后点击“我看懂了结果，进入小测”。'],quiz:['现在：检查理解','下一步：选择答案并检查，答对后手动进入下一课。']};const c=cues[phase]||cues.learn;return `<div class="flow-cue"><b>${c[0]}</b><span>本课目标：${esc(goal)}</span><span>${c[1]}</span></div>`;}
function pythonCourseHTML(){const c=pythonCurrent(),a=pythonAttempt(),passed=pythonPassed(pythonIndex),verified=a.result?.passed&&a.verifiedCode===a.code;return `<main class="hub-main python-main"><div class="lesson-top"><button class="text-button" data-python="roadmap">Python 学习路线</button><span class="chip">第 ${pythonIndex+1}/${pythonLessons.length} 课 · ${pythonStages[c.stage]}</span><button class="text-button" data-python="reset">重练本课</button></div><h1>${esc(c.title)}</h1>${pythonFlowCue(a.phase,c.goal)}<div class="learning-tabs" aria-label="本课学习步骤">${[['learn','1 · 理解'],['practice','2 · 写代码'],['quiz','3 · 小测']].map(([phase,title])=>`<button data-python="phase" data-phase="${phase}" aria-current="${a.phase===phase?'step':'false'}" ${phase==='practice'&&!a.read||phase==='quiz'&&!a.confirmed?'disabled':''}>${title}</button>`).join('')}</div>${a.phase==='learn'?`<section class="section"><h2>什么时候用得上？</h2><p>${esc(c.why)}</p><h2>用简单的话理解</h2><p>${esc(c.explain)}</p><h2>标准示例：先读懂每一行</h2><pre class="python-code">${esc(c.example)}</pre><ol>${c.lines.map(line=>`<li>${esc(line)}</li>`).join('')}</ol><h2>接下来要做什么？</h2><p>${esc(c.task)}</p><p>运行时会检查结果与本课要求的变量或函数。练习数据与示例不同，需要按任务修改代码。</p><button class="primary" data-python="read">我读懂了，开始写代码</button></section>`:a.phase==='practice'?`<section class="section"><h2>当前任务</h2><p>${esc(c.task)}</p><div class="python-expect"><b>正确输出应该是</b><pre>${esc(c.output)}</pre></div><div class="python-runtime" role="status"><span>${esc(pythonRuntimeNote||'首次练习：先准备 Python 环境，再运行代码。')}</span><button class="secondary" data-python="prepare" ${pythonRuntime!=='idle'?'disabled':''}>${pythonRuntime==='loading'?'正在准备…':pythonRuntime==='ready'?'Python 已就绪':'准备 Python 环境'}</button>${pythonRuntime==='loading'||pythonBusy?'<button class="secondary" data-python="stop">停止运行 / 加载</button>':''}</div><label for="python-code">你的代码（缩进建议使用四个空格）</label><textarea id="python-code" class="python-editor" wrap="off" rows="12" spellcheck="false" autocapitalize="off" autocomplete="off" maxlength="12000" ${pythonBusy?'disabled':''}>${esc(a.code)}</textarea><button class="primary" data-python="run" ${pythonRuntime!=='ready'||pythonBusy?'disabled':''}>${pythonBusy?'正在运行…':'运行代码并验证'}</button><button class="text-button" data-python="starter" ${pythonBusy?'disabled':''}>恢复起始代码</button><div class="python-result" aria-live="polite"><h3>运行结果</h3><pre class="hub-terminal">${esc(a.result?(a.result.output||'（没有输出）')+(a.result.error?'\n'+a.result.error:''):'尚未运行。')}</pre><p>${esc(a.result?.feedback||'运行后，先读输出和错误信息。')}</p></div><div class="gate-result"><strong>${verified?'代码与结果已验证':'尚未通过本课任务'}</strong><button class="primary" data-python="confirm" ${verified&&!pythonBusy?'':'disabled'}>${a.confirmed?'结果已确认，进入小测':'我看懂了结果，进入小测'}</button></div><details><summary>卡住了？查看参考解法与解释</summary><pre class="python-code">${esc(c.solution)}</pre><p>${esc(c.explain)}</p><p>可以参考写法，但仍需实际运行并通过校验。输出相同不代表函数在其他输入下也正确。</p></details></section>`:`<section class="section"><h2>${esc(c.quiz.prompt)}</h2><fieldset><legend>选择后点击检查，答错不会跳课</legend>${c.quiz.options.map((t,i)=>`<label class="hub-option ${a.answer===i?'is-selected':''}"><input type="radio" name="python-quiz" value="${i}" ${a.answer===i?'checked':''}><span>${esc(t)}</span></label>`).join('')}</fieldset><button class="primary" data-python="grade" ${a.answer===null?'disabled':''}>检查答案</button><p role="status">${a.checked?(passed?'回答正确，本课通过。':'尚未答对，请回看讲解再试。')+esc(c.quiz.explanation):'尚未检查当前答案。'}</p><div class="gate-result"><strong>${passed?'代码与小测均已通过':'通过练习与小测后解锁下一课'}</strong><button class="primary" data-python="next" ${passed?'':'disabled'}>${pythonIndex===pythonLessons.length-1?'查看学习成果':'进入第 '+(pythonIndex+2)+' 课'}</button></div><button class="text-button" data-python="phase" data-phase="learn">回看讲解</button></section>`}</main>`;}
const pythonBaseRender=render,pythonBaseSubject=subjectHTML;
subjectHTML=function(){return hubSubject==='python'?pythonRoadmapHTML():pythonBaseSubject();};
render=function(){if(pythonBusy&&!['python-course'].includes(view))pythonStop('已离开课堂，运行已停止；代码草稿保留。');if(view==='python-course'){$('app').innerHTML=hubNav()+pythonCourseHTML();return;}return pythonBaseRender();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-python]');if(!b||b.disabled)return;const d=b.dataset,a=pythonAttempt();if(d.python==='lesson')return pythonOpen(Number(d.index));if(d.python==='roadmap'){if(pythonBusy)pythonStop();hubSubject='python';view='subject';render();return;}if(d.python==='read'){a.read=true;a.phase='practice';}if(d.python==='phase'){if(d.phase==='practice'&&!a.read||d.phase==='quiz'&&!a.confirmed)return;a.phase=d.phase;}if(d.python==='prepare')return pythonPrepare();if(d.python==='stop')pythonStop();if(d.python==='run')return pythonRun();if(d.python==='confirm'){if(a.result?.passed&&a.verifiedCode===a.code&&!pythonBusy){a.confirmed=true;a.phase='quiz';}}if(d.python==='grade'){if(a.confirmed&&a.answer!==null)a.checked=true;}if(d.python==='next'){if(!pythonPassed(pythonIndex))return;if(pythonIndex+1<pythonLessons.length)return pythonOpen(pythonIndex+1);hubSubject='python';view='subject';}if(d.python==='starter'&&!pythonBusy){a.code=pythonCurrent().starter;a.result=null;pythonInvalidate(a);}if(d.python==='reset'){if(pythonBusy)pythonStop();delete pythonState[pythonCurrent().id];pythonAttempt();}pythonSave();render();if(['read','phase','confirm','next','reset'].includes(d.python))window.scrollTo({top:0,behavior:'instant'});});
document.addEventListener('input',e=>{if(e.target.id!=='python-code')return;const a=pythonAttempt();a.code=e.target.value;pythonInvalidate(a);pythonSave();const verdict=document.querySelector(".python-result p");if(verdict)verdict.textContent="代码已修改，旧结果不再代表当前代码；请重新运行。";const gate=document.querySelector(".gate-result strong");if(gate)gate.textContent="代码已修改，等待重新验证";const button=document.querySelector('[data-python="confirm"]');if(button)button.disabled=true;});
document.addEventListener('keydown',e=>{if(e.target.id==='python-code'&&e.key==='Tab'){e.preventDefault();const t=e.target,start=t.selectionStart,end=t.selectionEnd;t.value=t.value.slice(0,start)+'    '+t.value.slice(end);t.selectionStart=t.selectionEnd=start+4;t.dispatchEvent(new Event('input',{bubbles:true}));}});
document.addEventListener('change',e=>{if(e.target.name==='python-quiz'){const a=pythonAttempt();a.answer=Number(e.target.value);a.checked=false;pythonSave();render();}});
render();
